import React, { useEffect } from 'react';
import { BrowserRouter as Router, Route, Routes, Navigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { checkAuthStatus } from './redux/slices/authSlice';
import './App.css';

// Layout Components
import Header from './components/layout/Header';
import Footer from './components/layout/Footer';
import PrivateRoute from './components/auth/PrivateRoute';
import Navbar from './components/Navbar';

// Pages
import Home from './pages/Home';
import Login from './pages/Login';
import Register from './pages/Register';
import Dashboard from './pages/Dashboard';
import TherapyChat from './pages/TherapyChat';
import TherapyHistory from './pages/TherapyHistory';
import Journal from './pages/Journal';
import JournalEntry from './pages/JournalEntry';
import JournalEditor from './pages/JournalEditor';
import MoodTracker from './pages/MoodTracker';
import Profile from './pages/Profile';
import MoodHistory from './pages/MoodHistory';
import NotFound from './pages/NotFound';

function App() {
  const dispatch = useDispatch();
  const { isAuthenticated, checking } = useSelector(state => state.auth);

  useEffect(() => {
    dispatch(checkAuthStatus());
  }, [dispatch]);

  // Protected route component
  const ProtectedRoute = ({ children }) => {
    if (checking) return <div className="loading-screen">Loading...</div>;
    if (!isAuthenticated) return <Navigate to="/login" />;
    return children;
  };

  return (
    <Router>
      <div className="app">
        {isAuthenticated && <Navbar />}
        <main className="main-content">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/login" element={<Login />} />
            <Route path="/register" element={<Register />} />

            {/* Protected Routes */}
            <Route path="/dashboard" element={
              <ProtectedRoute>
                <Dashboard />
              </ProtectedRoute>
            } />

            <Route path="/therapy" element={
              <ProtectedRoute>
                <TherapyChat />
              </ProtectedRoute>
            } />

            <Route path="/therapy-history" element={
              <ProtectedRoute>
                <TherapyHistory />
              </ProtectedRoute>
            } />

            <Route path="/journal" element={
              <ProtectedRoute>
                <Journal />
              </ProtectedRoute>
            } />

            <Route path="/journal/new" element={
              <ProtectedRoute>
                <JournalEditor />
              </ProtectedRoute>
            } />

            <Route path="/journal/:entryId" element={
              <ProtectedRoute>
                <JournalEntry />
              </ProtectedRoute>
            } />

            <Route path="/journal/:entryId/edit" element={
              <ProtectedRoute>
                <JournalEditor />
              </ProtectedRoute>
            } />

            <Route path="/mood-tracker" element={
              <ProtectedRoute>
                <MoodTracker />
              </ProtectedRoute>
            } />

            <Route path="/mood-history" element={
              <ProtectedRoute>
                <MoodHistory />
              </ProtectedRoute>
            } />

            <Route path="/profile" element={
              <ProtectedRoute>
                <Profile />
              </ProtectedRoute>
            } />

            {/* 404 Route */}
            <Route path="*" element={<NotFound />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </Router>
  );
}

export default App;
